(function(){function fill(){document.querySelectorAll("img[data-goods-img]").forEach(function(im){var d=window.GOODS_IMAGES[im.getAttribute("data-goods-img")];if(d)im.src=d;});}if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",fill);else fill();})();